/* ==========================================================================
   dict.js — 영어 단어 사전 (3~8글자)
   --------------------------------------------------------------------------
   출처: ENABLE word list (public domain) ∩ 뜻을 확보한 단어

   필터
     · 순수 소문자 알파벳 단어만  → 고유명사·약어·숫자 섞인 문자열 제외
     · 3글자 미만 제외        → 두 글자가 단어로 굳으면 긴 단어를 못 만든다
     · 뜻이 확인된 단어만 채택    → 만든 단어는 반드시 더블클릭으로 뜻을 볼 수 있다

   길이별로 구분자 없이 이어붙인 고정폭 문자열. 로드 시 Set 으로 펼친다.
   여기 있는 단어는 전부 만들 수 있고, 재화를 번다.
   그중 37개(data.js 의 G.WORDS)만 특별한 능력을 가진다.
   총 65014개
   ========================================================================== */
var G = window.G || (window.G = {});

G.MIN_WORD_LEN = 3;
G.MAX_WORD_LEN = 8;

G.DICT_RAW = {
  3: "",
  4: "",
  5: "",
  6: "",
  7: "",
  8: ""
};

(function () {
  /* 길이별 원문은 버리지 않고 들고 있는다 (약 430KB).
     "아직 단어는 아니지만 더 붙이면 단어가 되는 조각" 을 판정할 때 쓴다. */
  var RAW = G.DICT_RAW;
  var GROW = Object.create(null);

  G.DICT = (function () {
    var set = Object.create(null), n, s, i, L;
    for (n in RAW) {
      L = +n; s = RAW[n];
      for (i = 0; i < s.length; i += L) set[s.substr(i, L)] = 1;
    }
    return set;
  })();

  /** 이 글자열이 만들 수 있는 단어인가 */
  G.isWord = function (t) { return G.DICT[t] === 1; };

  /**
   * 이 조각으로 시작하거나 끝나는 단어가 사전에 있는가.
   * 즉 "MOTHE" 처럼 아직 단어는 아니어도 더 붙이면 (MOTHER) 단어가 되는가.
   *
   * 원문이 구분자 없는 고정폭 문자열이라, 조각이 나타난 위치가 칸 경계에
   * 딱 맞는지만 보면 된다 — 칸 시작이면 그 단어의 머리, 칸 끝이면 꼬리다.
   * 드래그하는 내내 같은 조각을 되묻게 되므로 결과를 기억해 둔다.
   */
  G.canGrow = function (frag) {
    if (!frag || frag.length < 2 || frag.length >= G.MAX_WORD_LEN) return false;
    var hit = GROW[frag];
    if (hit !== undefined) return hit;

    hit = false;
    var k = frag.length;
    for (var n in RAW) {
      var L = +n;
      if (L <= k) continue;
      var s = RAW[n], i = s.indexOf(frag);
      while (i >= 0) {
        var off = i % L;
        if (off === 0 || off + k === L) { hit = true; break; }
        i = s.indexOf(frag, i + 1);
      }
      if (hit) break;
    }
    GROW[frag] = hit;
    return hit;
  };
})();
